import{_ as e,o as l,c as d,aB as a}from"./chunks/framework.B1IvnFrq.js";const g=JSON.parse('{"title":"Feature Coverage","description":"","frontmatter":{},"headers":[],"relativePath":"feature-coverage.md","filePath":"feature-coverage.md","lastUpdated":null}'),r={name:"feature-coverage.md"};function s(n,t,i,o,c,u){return l(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="Feature-Coverage" tabindex="-1">Feature Coverage <a class="header-anchor" href="#Feature-Coverage" aria-label="Permalink to &quot;Feature Coverage {#Feature-Coverage}&quot;">​</a></h1><p>This page summarizes the supported surface. The repository root <code>FEATURES_COVERAGE.md</code> remains the detailed tracking file for implementation notes and intentionally omitted edge cases.</p><h2 id="Core-NATS" tabindex="-1">Core NATS <a class="header-anchor" href="#Core-NATS" aria-label="Permalink to &quot;Core NATS {#Core-NATS}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Connect handshake</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes authentication fields, client name, no echo, TLS requirements, and server INFO parsing.</td></tr><tr><td style="text-align:left;">Publish and subscribe</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes wildcards, queue groups, headers, max payload checks, buffered outbound writes, and per-subscription pending limits.</td></tr><tr><td style="text-align:left;">Request reply</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Uses a shared request inbox mux and maps no-responder status to <code>NoRespondersError</code>.</td></tr><tr><td style="text-align:left;">Direct APIs and task handles</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Direct calls are task-friendly; <code>_async</code> helpers return <code>NatterTask</code> for explicit handle-oriented code.</td></tr><tr><td style="text-align:left;">Flush and ping</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Drains buffered outbound writes and uses PING/PONG synchronization.</td></tr><tr><td style="text-align:left;">Drain and close</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Drains subscriptions and reports cleanup failures.</td></tr><tr><td style="text-align:left;">Automatic reconnect</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Reconnects in the background, replays subscriptions, and flushes bounded pending publishes. Real-server coverage includes same-server reconnect and multi-URL failover; multi-node cluster chaos, discovered-route churn, and auth failover need more coverage before treating this as fully hardened cluster behavior.</td></tr><tr><td style="text-align:left;">Discovered servers</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Server-discovered URLs are retained for reconnects; discovered-route churn under cluster changes still needs real-server hardening.</td></tr><tr><td style="text-align:left;">Server errors</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Permission violations are reported without reconnecting; repeated auth failures abort reconnect with auth-specific errors.</td></tr><tr><td style="text-align:left;">Slow consumer handling</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Drops over-limit messages and reports <code>SlowConsumerError</code>.</td></tr><tr><td style="text-align:left;">WebSocket transport</td><td style="text-align:left;">Not implemented</td><td style="text-align:left;">Planned only if there is clear demand.</td></tr></tbody></table><h2 id="TLS-And-Security" tabindex="-1">TLS And Security <a class="header-anchor" href="#TLS-And-Security" aria-label="Permalink to &quot;TLS And Security {#TLS-And-Security}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">TLS-first handshake</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>tls://</code> defaults to TLS before INFO.</td></tr><tr><td style="text-align:left;">INFO-first TLS upgrade</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Use <code>tls_first=false</code> for deployments that require it.</td></tr><tr><td style="text-align:left;">CA and client certificates</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>tls_ca_path</code>, <code>tls_cert_path</code>, and <code>tls_key_path</code>.</td></tr><tr><td style="text-align:left;">Disable certificate verification</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>tls_verify=false</code>; intended only for trusted environments.</td></tr><tr><td style="text-align:left;">nkeys and JWT credentials</td><td style="text-align:left;">Not implemented</td><td style="text-align:left;">Authentication currently covers token and user/password credentials.</td></tr></tbody></table><h2 id="JetStream" tabindex="-1">JetStream <a class="header-anchor" href="#JetStream" aria-label="Permalink to &quot;JetStream {#JetStream}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Typed stream configs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Mirrors known stream schema fields with Julia structs and EnumX enums.</td></tr><tr><td style="text-align:left;">Typed consumer configs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Mirrors known consumer schema fields with Julia structs and EnumX enums.</td></tr><tr><td style="text-align:left;">Raw config dictionaries</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Escape hatch for newer server fields.</td></tr><tr><td style="text-align:left;">Stream CRUD and list APIs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes pagination.</td></tr><tr><td style="text-align:left;">Consumer CRUD and list APIs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes server-version-aware create subjects, strict create/update actions, and explicit create-or-update upsert.</td></tr><tr><td style="text-align:left;">Publish acknowledgements</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>js_publish</code> returns <code>PubAck</code>.</td></tr><tr><td style="text-align:left;">Task handle helpers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Management, publish, message get/delete, consumer, fetch, close, and ack operations have <code>_async</code> helpers.</td></tr><tr><td style="text-align:left;">Pull consumers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Durable and named consumers bind without mutation; missing consumers and random ephemerals are strictly created. Batch fetch, expiration handling, idle heartbeat monitoring, and JetStream status/control error mapping are covered.</td></tr><tr><td style="text-align:left;">Push consumers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Durable and named consumers bind without mutation; queue groups, callbacks, and manual or automatic acknowledgement are supported. Non-queue push consumers also support idle heartbeat filtering, missed-heartbeat reporting, flow-control replies, and lifecycle status reporting.</td></tr><tr><td style="text-align:left;">Message acknowledgements</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>ack</code>, <code>ack_sync</code>, <code>nak</code>, <code>in_progress</code>, and <code>term</code>.</td></tr><tr><td style="text-align:left;">Message get</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Sequence, last by subject, next by subject, and direct get.</td></tr><tr><td style="text-align:left;">Ordered consumers</td><td style="text-align:left;">Not implemented</td><td style="text-align:left;">Can be added later if needed.</td></tr><tr><td style="text-align:left;">Object store</td><td style="text-align:left;">Not implemented</td><td style="text-align:left;">Outside the current high-value surface.</td></tr></tbody></table><h2 id="KeyValue" tabindex="-1">KeyValue <a class="header-anchor" href="#KeyValue" aria-label="Permalink to &quot;KeyValue {#KeyValue}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Bucket create/open/delete/status</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Backed by JetStream streams; <code>kv_status</code> exposes values, history, TTL, storage, replicas, direct-read support, and the backing stream info.</td></tr><tr><td style="text-align:left;">Put/create/update</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Includes optimistic revision checks, create after delete/purge markers, and KV-specific conflict errors.</td></tr><tr><td style="text-align:left;">Get by latest or revision</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Returns typed entries with key, value, revision, created timestamp, delta, and operation. Direct reads are used when bucket direct access is enabled; missing and deleted keys raise KV-specific errors.</td></tr><tr><td style="text-align:left;">Delete and purge</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Uses KeyValue operation headers.</td></tr><tr><td style="text-align:left;">History and keys</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Implemented through pull consumers; history returns typed entries.</td></tr><tr><td style="text-align:left;">Watch</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Implemented through push consumers and typed entry callbacks.</td></tr><tr><td style="text-align:left;">Task handle helpers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Bucket, status, key, history, keys, and watch operations have <code>_async</code> helpers.</td></tr></tbody></table>',10)])])}const y=e(r,[["render",s]]);export{g as __pageData,y as default};
